//! Checks ssdeep and TLSH against results saved from ssdeep 2.14.1 and TLSH
//! 5.0.2 (`vectors.zig`, written by scripts/reference-vectors.mjs). The inputs
//! are regenerated by `corpus.zig`.

const std = @import("std");
const fuzzyhash = @import("fuzzyhash");
const corpus = @import("corpus.zig");
const vectors = @import("vectors.zig");

const Ssdeep = fuzzyhash.Ssdeep;
const Tlsh = fuzzyhash.Tlsh;
const testing = std.testing;
const gpa = testing.allocator;

const variants = [4]Tlsh.Variant{
    .{ .buckets = .b128, .checksum = .one },
    .{ .buckets = .b128, .checksum = .three },
    .{ .buckets = .b256, .checksum = .one },
    .{ .buckets = .b256, .checksum = .three },
};

fn ssdeepString(bytes: []const u8, buf: *[Ssdeep.max_string_length]u8) ![]const u8 {
    const d = try Ssdeep.hash(bytes, .{});
    return d.toString(buf);
}

/// The TLSH digest as the reference program prints it, or null.
fn tlshString(comptime v: Tlsh.Variant, bytes: []const u8, buf: *[Tlsh.Tlsh(v).max_string_length]u8) ?[]const u8 {
    const T = Tlsh.Tlsh(v);
    const d = T.hash(bytes, .{}) catch |err| switch (err) {
        error.TooShort, error.InsufficientVariation => return null,
        error.InputTooLarge => unreachable,
    };
    return d.toString(buf, .{});
}

/// The reference program prints `T1` for every build, but only the 128/1
/// build reads it back.
fn unprefixed(comptime T: type, digest: []const u8) []const u8 {
    if (T.parses_prefix or !std.mem.startsWith(u8, digest, "T1")) return digest;
    return digest[2..];
}

fn expectOptionalString(expected: ?[]const u8, actual: ?[]const u8) !void {
    if (expected) |e| {
        try testing.expect(actual != null);
        try testing.expectEqualStrings(e, actual.?);
    } else try testing.expect(actual == null);
}

test "the corpus matches the inputs the vectors were made from" {
    for (vectors.cases) |c| {
        const bytes = try corpus.bytes(gpa, c.input);
        defer gpa.free(bytes);
        if (c.input.edits == 0) try testing.expectEqual(c.input.len, bytes.len);
    }
}

test "ssdeep digests match ssdeep 2.14.1" {
    var buf: [Ssdeep.max_string_length]u8 = undefined;
    for (vectors.cases, 0..) |c, i| {
        const bytes = try corpus.bytes(gpa, c.input);
        defer gpa.free(bytes);
        const got = try ssdeepString(bytes, &buf);
        if (!std.mem.eql(u8, c.ssdeep, got)) {
            std.debug.print("case {d} ({t}, {d} bytes): want {s}, got {s}\n", .{ i, c.input.kind, bytes.len, c.ssdeep, got });
            return error.TestUnexpectedResult;
        }
    }
}

test "ssdeep streaming in uneven chunks gives the same digests" {
    var buf: [Ssdeep.max_string_length]u8 = undefined;
    for (vectors.cases) |c| {
        const bytes = try corpus.bytes(gpa, c.input);
        defer gpa.free(bytes);
        var h = Ssdeep.init(.{});
        var at: usize = 0;
        var step: usize = 1;
        while (at < bytes.len) : (step = step * 3 % 4099 + 1) {
            const n = @min(step, bytes.len - at);
            h.update(bytes[at..][0..n]);
            at += n;
        }
        const d = try h.final();
        try testing.expectEqualStrings(c.ssdeep, d.toString(&buf));
    }
}

test "ssdeep scores match ssdeep 2.14.1" {
    for (vectors.pairs) |p| {
        const a = vectors.cases[p.a].ssdeep;
        const b = vectors.cases[p.b].ssdeep;
        try testing.expectEqual(p.ssdeep, try Ssdeep.compareStrings(a, b));
    }
}

test "TLSH digests match TLSH 5.0.2, all four builds" {
    inline for (variants, 0..) |v, k| {
        var buf: [Tlsh.Tlsh(v).max_string_length]u8 = undefined;
        for (vectors.cases, 0..) |c, i| {
            const bytes = try corpus.bytes(gpa, c.input);
            defer gpa.free(bytes);
            const got = tlshString(v, bytes, &buf);
            expectOptionalString(c.tlsh[k], got) catch |err| {
                std.debug.print("TLSH {s}, case {d} ({t}, {d} bytes): want {?s}, got {?s}\n", .{ vectors.tlsh_variants[k], i, c.input.kind, bytes.len, c.tlsh[k], got });
                return err;
            };
        }
    }
}

test "TLSH streaming in uneven chunks gives the same digests" {
    inline for (variants, 0..) |v, k| {
        const T = Tlsh.Tlsh(v);
        var buf: [T.max_string_length]u8 = undefined;
        for (vectors.cases) |c| {
            const want = c.tlsh[k] orelse continue;
            const bytes = try corpus.bytes(gpa, c.input);
            defer gpa.free(bytes);
            var h = T.init(.{});
            var at: usize = 0;
            var step: usize = 1;
            while (at < bytes.len) : (step = step * 5 % 3001 + 1) {
                const n = @min(step, bytes.len - at);
                h.update(bytes[at..][0..n]);
                at += n;
            }
            const d = try h.final();
            try testing.expectEqualStrings(want, d.toString(&buf, .{}));
        }
    }
}

test "TLSH distances match TLSH 5.0.2, with and without the length term" {
    inline for (variants, 0..) |v, k| {
        const T = Tlsh.Tlsh(v);
        for (vectors.pairs) |p| {
            const want = p.tlsh_diff[k] orelse continue;
            const want_xlen = p.tlsh_diff_xlen[k].?;
            const a = try T.Digest.parse(unprefixed(T, vectors.cases[p.a].tlsh[k].?));
            const b = try T.Digest.parse(unprefixed(T, vectors.cases[p.b].tlsh[k].?));
            try testing.expectEqual(want, T.diff(a, b, .{}));
            try testing.expectEqual(want_xlen, T.diff(a, b, .{ .include_length = false }));
        }
    }
}
